  package.json
  por-mc.mjs                 # checker + CLI + artifact emitter
  verify.mjs                 # end-to-end verification
  fuzz.mjs                   # randomized differential fuzzer
  programs/
    independent_chain.json   # deadlock, big reduction
    deadlock_free_chain.json # no deadlock, big reduction
    missed_deadlock.json     # counterexample: naive POR misses the deadlock
