```

### 2.4 Run it

```bash
cd por-mc
node por-mc.mjs                 # run all programs, write artifacts/, print report
node por-mc.mjs programs/missed_deadlock.json
node verify.mjs                 # determinism + differential + counterexample + fuzz
node fuzz.mjs 15000             # differential fuzz only
```

### 2.5 Full source

#### `por-mc.mjs`

```js
#!/usr/bin/env node
// por-mc.mjs -- state-space model checker for a small CSP-style language.
//
// Input: JSON program with shared variables, processes with a local location,
// and guarded atomic transitions whose effects assign shared variables.
//
// The checker:
//   1. exhaustively explores the interleaving state space (BFS) -> shortest deadlock
//   2. explores a partial-order-reduced state space using ample/stubborn sets
//      with the classic C0..C3 conditions
//   3. runs a deliberately dependency-blind POR to demonstrate unsoundness
//   4. emits a differential artifact proving the reduced search agrees with the
//      full search while doing strictly less work.
//
// Everything is deterministic: processes are visited in array order, transitions
// in array order, effect keys in sorted order, BFS is FIFO, and reduced-graph
// adjacency is sorted by transition index.

import fs from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';

// ---------------------------------------------------------------------------
// Expression language (safe, dependency-free): == != < <= > >= && || ! + - * / %
// ---------------------------------------------------------------------------

const TWO_CHAR_OPS = new Set(['==', '!=', '<=', '>=', '&&', '||']);

function tokenize(src) {
  const tokens = [];
  let i = 0;
  const isDigit = (c) => c >= '0' && c <= '9';
  const isAlpha = (c) => /[A-Za-z_]/.test(c);
  const isAlnum = (c) => /[A-Za-z0-9_]/.test(c);
  while (i < src.length) {
    const c = src[i];
    if (/\s/.test(c)) { i++; continue; }
    const two = src.slice(i, i + 2);
    if (TWO_CHAR_OPS.has(two)) { tokens.push({ type: 'op', value: two }); i += 2; continue; }
    if ('+-*/%!<>'.includes(c)) { tokens.push({ type: 'op', value: c }); i++; continue; }
    if (c === '(' || c === ')') { tokens.push({ type: 'punc', value: c }); i++; continue; }
    if (isDigit(c)) {
      let j = i; while (j < src.length && isDigit(src[j])) j++;
      tokens.push({ type: 'num', value: Number(src.slice(i, j)) }); i = j; continue;
    }
    if (isAlpha(c)) {
      let j = i; while (j < src.length && isAlnum(src[j])) j++;
      tokens.push({ type: 'ident', value: src.slice(i, j) }); i = j; continue;
    }
    throw new Error(`Unexpected character '${c}' in expression: ${src}`);
  }
  tokens.push({ type: 'eof' });
  return tokens;
}

function parseExpression(src) {
  const tokens = tokenize(src);
  let pos = 0;
  const peek = () => tokens[pos];
  const next = () => tokens[pos++];

  function parseOr() {
    let left = parseAnd();
    while (peek().type === 'op' && peek().value === '||') {
      next();
      left = { type: 'binary', op: '||', left, right: parseAnd() };
    }
    return left;
  }
  function parseAnd() {
    let left = parseCmp();
    while (peek().type === 'op' && peek().value === '&&') {
      next();
      left = { type: 'binary', op: '&&', left, right: parseCmp() };
    }
    return left;
  }
  function parseCmp() {
    const left = parseAdd();
    const t = peek();
    if (t.type === 'op' && ['==', '!=', '<', '<=', '>', '>='].includes(t.value)) {
      next();
      return { type: 'binary', op: t.value, left, right: parseAdd() };
    }
    return left;
  }
  function parseAdd() {
    let left = parseMul();
    while (peek().type === 'op' && (peek().value === '+' || peek().value === '-')) {
      const op = next().value;
      left = { type: 'binary', op, left, right: parseMul() };
    }
    return left;
  }
  function parseMul() {
    let left = parseUnary();
    while (peek().type === 'op' && ['*', '/', '%'].includes(peek().value)) {
      const op = next().value;
      left = { type: 'binary', op, left, right: parseUnary() };
    }
    return left;
  }
  function parseUnary() {
    if (peek().type === 'op' && (peek().value === '!' || peek().value === '-')) {
      const op = next().value;
      return { type: 'unary', op, operand: parseUnary() };
    }
    return parsePrimary();
  }
  function parsePrimary() {
    const t = next();
    if (t.type === 'num') return { type: 'num', value: t.value };
    if (t.type === 'ident') {
      if (t.value === 'true') return { type: 'bool', value: true };
      if (t.value === 'false') return { type: 'bool', value: false };
      return { type: 'var', name: t.value };
    }
    if (t.type === 'punc' && t.value === '(') {
      const e = parseOr();
      const close = next();
      if (close.value !== ')') throw new Error(`Expected ')' in expression: ${src}`);
      return e;
    }
    throw new Error(`Unexpected token in expression: ${src}`);
  }

  const ast = parseOr();
  if (peek().type !== 'eof') throw new Error(`Trailing tokens in expression: ${src}`);
  return ast;
}

function truthy(v) { return v === true || (typeof v === 'number' && v !== 0) || (typeof v === 'string' && v.length > 0); }

function evaluate(ast, env) {
  switch (ast.type) {
    case 'num': return ast.value;
    case 'bool': return ast.value;
    case 'var': {
      if (!(ast.name in env)) throw new Error(`Unbound variable '${ast.name}'`);
      return env[ast.name];
    }
    case 'unary': {
      const v = evaluate(ast.operand, env);
      return ast.op === '!' ? !truthy(v) : -v;
    }
    case 'binary': {
      if (ast.op === '&&') return truthy(evaluate(ast.left, env)) && truthy(evaluate(ast.right, env));
      if (ast.op === '||') return truthy(evaluate(ast.left, env)) || truthy(evaluate(ast.right, env));
      const a = evaluate(ast.left, env);
      const b = evaluate(ast.right, env);
      switch (ast.op) {
        case '==': return a === b;
        case '!=': return a !== b;
        case '<': return a < b;
        case '<=': return a <= b;
        case '>': return a > b;
        case '>=': return a >= b;
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': return Math.trunc(a / b);
        case '%': return a % b;
        default: throw new Error(`Unknown operator ${ast.op}`);
      }
    }
    default: throw new Error(`Unknown AST node ${ast.type}`);
  }
}

function collectIdents(ast, out = new Set()) {
  if (!ast) return out;
  switch (ast.type) {
    case 'var': out.add(ast.name); break;
    case 'unary': collectIdents(ast.operand, out); break;
    case 'binary': collectIdents(ast.left, out); collectIdents(ast.right, out); break;
    default: break;
  }
  return out;
}

// ---------------------------------------------------------------------------
// Program model
// ---------------------------------------------------------------------------

function loadProgram(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function buildModel(prog) {
  const sharedVars = Object.keys(prog.shared || {}).sort();
  const initShared = {};
  for (const v of sharedVars) initShared[v] = prog.shared[v];

  const sharedVarSet = new Set(sharedVars);
  const transitions = [];

  for (let pid = 0; pid < prog.processes.length; pid++) {
    const p = prog.processes[pid];
    for (let k = 0; k < p.transitions.length; k++) {
      const tr = p.transitions[k];
      const locVar = `@loc:${p.name}`;
      const guardAst = tr.guard == null ? null : parseExpression(String(tr.guard));
      const effectEntries = Object.keys(tr.effect || {}).sort()
        .map((v) => [v, parseExpression(String(tr.effect[v]))]);
      const reads = new Set(collectIdents(guardAst));
      const writes = new Set();
      for (const [v, ast] of effectEntries) {
        writes.add(v);
        for (const id of collectIdents(ast)) reads.add(id);
      }
      reads.add(locVar);
      writes.add(locVar);
      transitions.push({
        index: transitions.length,
        pid,
        pname: p.name,
        tid: k,
        label: tr.label || `t${k}`,
        from: tr.from,
        to: tr.to,
        guard: tr.guard == null ? 'true' : String(tr.guard),
        guardAst,
        effectEntries,
        reads,
        writes,
        locVar,
      });
    }
  }

  // Dependency matrix: two transitions are dependent iff they touch a common
  // variable with at least one writer (this includes the process location, so
  // two transitions of the same process are always dependent).
  const dep = transitions.map(() => new Array(transitions.length).fill(false));
  for (let a = 0; a < transitions.length; a++) {
    for (let b = 0; b < transitions.length; b++) {
      const A = transitions[a], B = transitions[b];
      let conflict = false;
      for (const v of A.writes) if (B.reads.has(v) || B.writes.has(v)) { conflict = true; break; }
      if (!conflict) for (const v of B.writes) if (A.reads.has(v) || A.writes.has(v)) { conflict = true; break; }
      dep[a][b] = conflict;
    }
  }

  const visibleVars = new Set(prog.visibleVars || []);
  const visible = transitions.map((t) => {
    for (const v of t.writes) if (visibleVars.has(v)) return true;
    return false;
  });

  const model = {
    name: prog.name || path.basename('program'),
    sharedVars,
    observations: prog.observations || [],
    processNames: prog.processes.map((p) => p.name),
    transitions,
    dep,
    visible,
    initState: { shared: { ...initShared }, locs: prog.processes.map((p) => p.init) },
  };

  model.key = (s) => stateKey(model, s);
  model.enabled = (s) => enabledTransitions(model, s);
  model.apply = (s, ti) => applyTransition(model, s, ti);
  model.describe = (ti) => {
    const t = model.transitions[ti];
    return `${t.pname}.${t.label}`;
  };
  return model;
}

function stateKey(_model, s) {
  return JSON.stringify([s.shared, s.locs]);
}

function enabledTransitions(model, s) {
  const res = [];
  for (let ti = 0; ti < model.transitions.length; ti++) {
    const t = model.transitions[ti];
    if (s.locs[t.pid] !== t.from) continue;
    if (t.guardAst !== null && !truthy(evaluate(t.guardAst, s.shared))) continue;
    res.push(ti);
  }
  return res;
}

function applyTransition(model, s, ti) {
  const t = model.transitions[ti];
  const newShared = { ...s.shared };
  // Simultaneous assignment: all right-hand sides see the pre-state.
  const pending = [];
  for (const [v, ast] of t.effectEntries) pending.push([v, evaluate(ast, s.shared)]);
  for (const [v, val] of pending) newShared[v] = val;
  const locs = s.locs.slice();
  locs[t.pid] = t.to;
  return { shared: newShared, locs };
}

// ---------------------------------------------------------------------------
// Ample / stubborn set computation with C0..C3
// ---------------------------------------------------------------------------

// Dependency closure over ALL transitions (enabled or not). Starting from an
// enabled seed this yields a stubborn set: every transition that conflicts with
// a member is a member, so anything left out is independent of everything
// inside and can never enable a member. We branch only on the enabled subset.
function stubbornClosure(seed, transitions, dep) {
  const inSet = new Set([seed]);
  const queue = [seed];
  while (queue.length) {
    const t = queue.shift();
    for (let u = 0; u < transitions.length; u++) {
      if (!inSet.has(u) && dep[t][u]) { inSet.add(u); queue.push(u); }
    }
  }
  return inSet;
}

// Compute the ample set and record the reasoning for the differential artifact.
function computeAmple(model, s) {
  const enabled = enabledTransitions(model, s);
  const record = {
    state: model.key(s),
    enabled: enabled.map((i) => model.describe(i)),
    enabledIdx: enabled.slice(),
    seed: null,
    closure: [],
    naiveCandidate: null,
    naiveRejected: false,
    rejectReason: [],
    conditions: { C0: null, C1: null, C2: null, C3: null },
  };

  // C0: empty ample iff no enabled transition.
  if (enabled.length === 0) {
    record.conditions.C0 = { passed: true, note: 'no enabled transitions => deadlock state' };
    return { ample: [], full: true, record };
  }

  const seed = enabled[0];
  record.seed = model.describe(seed);
  record.naiveCandidate = [model.describe(seed)];

  const closure = stubbornClosure(seed, model.transitions, model.dep);
  record.closure = [...closure].sort((a, b) => a - b).map((i) => model.describe(i));

  const ample = enabled.filter((i) => closure.has(i));

  // Did the dependency closure enlarge the naive single-transition candidate?
  const added = ample.filter((i) => i !== seed);
  if (added.length > 0) {
    record.naiveRejected = true;
    record.rejectReason.push(
      `C1: enabled transition(s) ${added.map((i) => model.describe(i)).join(', ')} ` +
      `depend on ${model.describe(seed)} and must be in the ample set`
    );
  }

  // C1: the enabled restriction must be closed under dependence.
  let c1 = true;
  for (const t of ample) {
    for (const u of enabled) {
      if (model.dep[t][u] && !ample.includes(u)) { c1 = false; break; }
    }
    if (!c1) break;
  }
  record.conditions.C1 = { passed: c1, note: c1 ? 'ample closed under enabled dependencies' : 'enabled dependent transition omitted' };

  // C2: for a proper subset, every ample transition must be invisible w.r.t. the
  // checked property. For pure deadlock detection the property is a state
  // predicate, so transitions are invisible unless the user names visibleVars.
  let c2 = true;
  if (ample.length !== enabled.length) {
    for (const t of ample) if (model.visible[t]) { c2 = false; break; }
  }
  record.conditions.C2 = {
    passed: c2,
    note: ample.length === enabled.length ? 'fully expanded, C2 vacuous' : (c2 ? 'ample transitions invisible' : 'visible transition in proper ample set'),
  };

  // If C1/C2 do not hold, fall back to full expansion. (With the all-transition
  // closure C1 always holds; this is a belt-and-braces guard.)
  if (!c1 || !c2) {
    record.conditions.C0 = { passed: true, note: 'nonempty enabled set' };
    record.conditions.C3 = { passed: true, note: 'full expansion' };
    return { ample: enabled, full: true, record };
  }

  record.conditions.C0 = { passed: true, note: 'nonempty enabled set' };
  record.conditions.C3 = { passed: true, note: 'checked during reduced-graph construction' };
  return { ample, full: ample.length === enabled.length, record };
}

// ---------------------------------------------------------------------------
// Full exploration (BFS)
// ---------------------------------------------------------------------------

function bfs(model, adjacency) {
  const init = model.initState;
  const initKey = model.key(init);
  const parent = new Map([[initKey, null]]);
  const queue = [init];
  const adjacencyStore = new Map();
  let exploredTransitions = 0;
  let expandedStates = 0;
  let deadlockKey = null;
  let deadlockTransitions = 0;

  while (queue.length > 0) {
    const s = queue.shift();
    const key = model.key(s);
    const enabled = model.enabled(s);
    const adj = adjacency ? adjacency(model, s, key, enabled) : enabled;
    adjacencyStore.set(key, adj);

    if (adj.length === 0) {
      deadlockKey = key;
      break;
    }
    expandedStates++;
    for (const ti of adj) {
      exploredTransitions++;
      const ns = model.apply(s, ti);
      const nk = model.key(ns);
      if (!parent.has(nk)) {
        parent.set(nk, { parentKey: key, ti });
        queue.push(ns);
      }
    }
  }

  const trace = [];
  if (deadlockKey !== null) {
    let k = deadlockKey;
    while (parent.get(k) !== null) {
      const { parentKey, ti } = parent.get(k);
      trace.push({ state: k, transition: model.describe(ti), ti });
      k = parentKey;
    }
    trace.push({ state: k, transition: null, ti: null });
    trace.reverse();
    deadlockTransitions = trace.length - 1;
  }

  return {
    deadlock: deadlockKey !== null,
    length: deadlockTransitions,
    exploredTransitions,
    expandedStates,
    reachableStates: parent.size,
    deadlockState: deadlockKey,
    trace,
    adjacency: adjacencyStore,
  };
}

// Dependency-blind POR: always branch on the first enabled transition and
// ignore all dependency information. This is the classic unsound reduction.
function naiveAdjacency(_model, _s, _key, enabled) {
  return enabled.length > 0 ? [enabled[0]] : [];
}

// Reduced graph built with a DFS that enforces the C3 cycle proviso: when the
// ample successors of the state currently on the DFS stack close a cycle, that
// state is expanded fully, guaranteeing every reduced cycle contains a fully
// expanded state.
function buildReducedGraph(model) {
  const nodes = new Map();  // key -> { state, ample, full, record }
  const edges = new Map();  // key -> [ti]
  const onStack = new Set();
  const diagnostics = [];
  let c3Forced = 0;

  function visit(state) {
    const key = model.key(state);
    if (nodes.has(key)) return;

    onStack.add(key);

    const { ample, full, record } = computeAmple(model, state);
    let finalAmple = ample;
    let finalFull = full;

    // C3 cycle proviso.
    if (!full) {
      const succKeys = ample.map((ti) => model.key(model.apply(state, ti)));
      const closesCycle = succKeys.some((k) => onStack.has(k));
      if (closesCycle) {
        finalAmple = model.enabled(state);
        finalFull = true;
        c3Forced++;
        record.naiveRejected = true;
        record.rejectReason.push('C3: ample successor is on the DFS stack (cycle); expanding fully so every reduced cycle has a fully expanded state');
        record.conditions.C3 = { passed: false, forcedFull: true, note: 'ample would close a cycle without a fully expanded state' };
      } else {
        record.conditions.C3 = { passed: true, note: 'no cycle closed by this ample set' };
      }
    }

    nodes.set(key, { state, ample: finalAmple, full: finalFull, record });
    diagnostics.push(record);

    const sorted = finalAmple.slice().sort((a, b) => a - b);
    edges.set(key, sorted);
    for (const ti of sorted) {
      const ns = model.apply(state, ti);
      visit(ns);
    }

    onStack.delete(key);
  }

  visit(model.initState);
  return { nodes, edges, diagnostics, c3Forced };
}

function runReduced(model) {
  const { nodes, edges, diagnostics, c3Forced } = buildReducedGraph(model);
  const adjacency = (_model, _s, key, enabled) => {
    if (edges.has(key)) return edges.get(key);
    return enabled; // unreachable safeguard
  };
  const result = bfs(model, adjacency);
  return { ...result, diagnostics, c3Forced, reducedNodes: nodes.size };
}

// ---------------------------------------------------------------------------
// Differential artifact
// ---------------------------------------------------------------------------

function ratio(num, den) { return den === 0 ? 0 : Number((num / den).toFixed(6)); }

function analyze(prog, sourceFile) {
  const model = buildModel(prog);
  const full = bfs(model, null);
  const naive = bfs(model, naiveAdjacency);
  const reduced = runReduced(model);

  const initialRecord = reduced.diagnostics.find((d) => d.state === model.key(model.initState)) || null;

  const checks = {
    sameVerdict: full.deadlock === reduced.deadlock,
    sameShortestLength: full.length === reduced.length,
    strictlyFewerTransitions: reduced.exploredTransitions < full.exploredTransitions,
    reductionRatio: ratio(full.exploredTransitions - reduced.exploredTransitions, full.exploredTransitions),
    naiveVerdictMatchesFull: naive.deadlock === full.deadlock,
  };

  const artifact = {
    program: prog.name || path.basename(sourceFile),
    source: sourceFile,
    full: {
      verdict: full.deadlock ? 'DEADLOCK' : 'DEADLOCK-FREE',
      shortestDeadlockLength: full.length,
      exploredTransitions: full.exploredTransitions,
      expandedStates: full.expandedStates,
      reachableStates: full.reachableStates,
      trace: full.trace.map((x) => x.transition ? `${x.transition}` : '(init)'),
    },
    amplePOR: {
      verdict: reduced.deadlock ? 'DEADLOCK' : 'DEADLOCK-FREE',
      shortestDeadlockLength: reduced.length,
      exploredTransitions: reduced.exploredTransitions,
      expandedStates: reduced.expandedStates,
      reachableStates: reduced.reachableStates,
      c3ForcedFullExpansions: reduced.c3Forced,
      trace: reduced.trace.map((x) => x.transition ? `${x.transition}` : '(init)'),
    },
    dependencyBlindPOR: {
      verdict: naive.deadlock ? 'DEADLOCK' : 'DEADLOCK-FREE',
      shortestDeadlockLength: naive.length,
      exploredTransitions: naive.exploredTransitions,
    },
    checks,
    ampleDiagnostic: initialRecord,
  };

  artifact.pass = checks.sameVerdict && checks.sameShortestLength && checks.strictlyFewerTransitions;
  return artifact;
}

// ---------------------------------------------------------------------------
// CLI
// ---------------------------------------------------------------------------

function readProgramList(args) {
  const files = [];
  for (const a of args) {
    if (a.startsWith('--')) continue;
    const st = fs.existsSync(a) ? fs.statSync(a) : null;
    if (st && st.isDirectory()) {
      for (const f of fs.readdirSync(a).sort()) if (f.endsWith('.json')) files.push(path.join(a, f));
    } else if (st && st.isFile()) {
      files.push(a);
    }
  }
  return files;
}

function main() {
  const args = process.argv.slice(2);
  const programDir = path.resolve(path.dirname(new URL(import.meta.url).pathname), 'programs');
  let files = readProgramList(args.length ? args : [programDir]);
  if (files.length === 0) {
    console.error('No program files given. Usage: node por-mc.mjs <program.json | programs-dir>');
    process.exit(2);
  }

  const artifacts = files.map((f) => analyze(loadProgram(f), path.relative(process.cwd(), f)));
  const summary = {
    node: process.version,
    programs: artifacts.length,
    allPass: artifacts.every((a) => a.pass),
    results: artifacts,
  };

  const outDir = path.resolve(path.dirname(new URL(import.meta.url).pathname), 'artifacts');
  fs.mkdirSync(outDir, { recursive: true });
  for (const a of artifacts) {
    fs.writeFileSync(path.join(outDir, `${a.program}.json`), JSON.stringify(a, null, 2));
  }
  fs.writeFileSync(path.join(outDir, 'summary.json'), JSON.stringify(summary, null, 2));

  // Human-readable report.
  for (const a of artifacts) {
    console.log(`\n=== ${a.program} (${a.source}) ===`);
    console.log(`full   : ${a.full.verdict.padEnd(13)} len=${a.full.shortestDeadlockLength} transitions=${a.full.exploredTransitions} states=${a.full.reachableStates}`);
    console.log(`ample  : ${a.amplePOR.verdict.padEnd(13)} len=${a.amplePOR.shortestDeadlockLength} transitions=${a.amplePOR.exploredTransitions} states=${a.amplePOR.reachableStates} c3Forced=${a.amplePOR.c3ForcedFullExpansions}`);
    console.log(`naive  : ${a.dependencyBlindPOR.verdict.padEnd(13)} len=${a.dependencyBlindPOR.shortestDeadlockLength} transitions=${a.dependencyBlindPOR.exploredTransitions}`);
    console.log(`checks : verdict=${a.checks.sameVerdict} length=${a.checks.sameShortestLength} fewer=${a.checks.strictlyFewerTransitions} ratio=${(a.checks.reductionRatio * 100).toFixed(1)}% naiveAgrees=${a.checks.naiveVerdictMatchesFull}`);
    if (!a.checks.sameVerdict || !a.checks.sameShortestLength || !a.checks.strictlyFewerTransitions) console.log('  ** CHECK FAILED **');
    if (a.full.trace.length) console.log(`  full trace : ${a.full.trace.join(' -> ')}`);
    if (a.amplePOR.trace.length) console.log(`  ample trace: ${a.amplePOR.trace.join(' -> ')}`);
    const d = a.ampleDiagnostic;
