```js
#!/usr/bin/env node
// Randomized differential fuzzing: full BFS vs ample-POR.
// Checks verdict AND shortest-deadlock length agree on many random programs.

import { buildModel, bfs, runReduced, analyze } from './por-mc.mjs';

// Deterministic PRNG so runs are reproducible.
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function pick(rnd, arr) { return arr[Math.floor(rnd() * arr.length)]; }
function int(rnd, n) { return Math.floor(rnd() * n); }

function genProgram(seed) {
  const rnd = mulberry32(seed);
  const nVars = 2 + int(rnd, 2);
  const nProc = 2 + int(rnd, 3);
  const vars = Array.from({ length: nVars }, (_, i) => `v${i}`);
  const shared = {};
  for (const v of vars) shared[v] = int(rnd, 2);

  const guardPool = ['true'];
  for (const v of vars) guardPool.push(`${v} == 0`, `${v} == 1`, `${v} < 1`, `${v} >= 0`, `${v} != 0`);
  const exprPool = ['0', '1'];
  for (const v of vars) exprPool.push(v, `1 - ${v}`, `${v} < 1`, `${v} == 0`, `${v} != 0`);

  const processes = [];
  for (let p = 0; p < nProc; p++) {
    const nLoc = 1 + int(rnd, 3);
    const transitions = [];
    for (let l = 0; l < nLoc; l++) {
      const nT = int(rnd, 4);
      for (let k = 0; k < nT; k++) {
        const effect = {};
        const nW = int(rnd, 2);
        for (let w = 0; w < nW; w++) effect[pick(rnd, vars)] = pick(rnd, exprPool);
        transitions.push({
          label: `t${l}_${k}`,
          from: l,
          guard: pick(rnd, guardPool),
          effect,
          to: int(rnd, nLoc),
        });
      }
    }
    processes.push({ name: `P${p}`, init: 0, transitions });
  }
  return { name: `fuzz_${seed}`, shared, processes };
}

const N = Number(process.argv[2] || 20000);
let mismatches = 0;
let lengthMismatch = 0;
let reducedNotLess = 0;
let tested = 0;

for (let seed = 1; seed <= N; seed++) {
  const prog = genProgram(seed);
  let model;
  try { model = buildModel(prog); } catch { continue; }
  let full, reduced;
  try {
    full = bfs(model, null);
    reduced = runReduced(model);
  } catch { continue; }
  tested++;
  if (full.deadlock !== reduced.deadlock) {
    mismatches++;
    console.log(`VERDICT MISMATCH seed=${seed} full=${full.deadlock} reduced=${reduced.deadlock}`);
    console.log(JSON.stringify(prog));
    if (mismatches >= 5) break;
  } else if (full.deadlock && full.length !== reduced.length) {
    lengthMismatch++;
    console.log(`LENGTH MISMATCH seed=${seed} full=${full.length} reduced=${reduced.length}`);
    console.log(JSON.stringify(prog));
    if (lengthMismatch >= 5) break;
  }
  if (reduced.exploredTransitions >= full.exploredTransitions) reducedNotLess++;
}

console.log(`\ntested=${tested} verdictMismatches=${mismatches} lengthMismatches=${lengthMismatch} nonStrictReduction=${reducedNotLess}`);
process.exit(mismatches === 0 && lengthMismatch === 0 ? 0 : 1);
```

