```js
#!/usr/bin/env node
// verify.mjs -- end-to-end verification of the model checker.
//
// 1. every shipped program: full == ample-POR verdict and shortest length,
//    ample-POR strictly fewer transitions, artifact emitted
// 2. determinism: two independent runs produce byte-identical artifacts
// 3. the counterexample program: dependency-blind POR disagrees with full
//    search while ample-POR does not
// 4. randomized differential fuzzing: no verdict/length mismatch

import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { analyze, loadProgram } from './por-mc.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const programDir = path.join(here, 'programs');
const files = fs.readdirSync(programDir).filter((f) => f.endsWith('.json')).sort()
  .map((f) => path.join(programDir, f));

let failures = 0;
const fail = (msg) => { failures++; console.log(`FAIL  ${msg}`); };
const ok = (msg) => console.log(`ok    ${msg}`);

// 1 + 2: analyze twice and compare
const first = [];
const second = [];
for (const f of files) {
  const prog = loadProgram(f);
  first.push(analyze(prog, f));
  second.push(analyze(prog, f));
}
const a1 = JSON.stringify(first);
const a2 = JSON.stringify(second);
if (a1 === a2) ok('determinism: two runs produce byte-identical artifacts');
else fail('determinism: artifacts differ between runs');

for (const a of first) {
  if (!a.checks.sameVerdict) fail(`${a.program}: verdict differs (full=${a.full.verdict}, por=${a.amplePOR.verdict})`);
  else if (!a.checks.sameShortestLength) fail(`${a.program}: shortest length differs (full=${a.full.shortestDeadlockLength}, por=${a.amplePOR.shortestDeadlockLength})`);
  else if (!a.checks.strictlyFewerTransitions) fail(`${a.program}: POR did not strictly reduce transitions (full=${a.full.exploredTransitions}, por=${a.amplePOR.exploredTransitions})`);
  else ok(`${a.program}: verdict+length preserved, transitions ${a.full.exploredTransitions} -> ${a.amplePOR.exploredTransitions} (ratio ${(a.checks.reductionRatio * 100).toFixed(1)}%)`);
}

// 3: dependency-blind counterexample
const miss = first.find((a) => a.program === 'missed_deadlock');
if (!miss) fail('counterexample program missed_deadlock not found');
else {
  if (miss.full.verdict === 'DEADLOCK' && miss.dependencyBlindPOR.verdict === 'DEADLOCK-FREE' && miss.amplePOR.verdict === 'DEADLOCK') {
    ok('counterexample: dependency-blind POR misses the real deadlock, ample-POR finds it');
  } else {
    fail('counterexample: expected naive to miss and ample to find the deadlock');
  }
  const d = miss.ampleDiagnostic;
  if (d && d.naiveRejected && d.rejectReason.length > 0) ok(`counterexample: ample computation rejects the naive reduction (${d.rejectReason.length} reason(s))`);
  else fail('counterexample: ample computation did not record a rejection');
}

// 4: fuzz (fixed seed range, deterministic)
try {
  const out = execFileSync(process.execPath, [path.join(here, 'fuzz.mjs'), '8000'], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
  const line = out.trim().split('\n').filter((l) => l.startsWith('tested=')).pop();
  if (line && /verdictMismatches=0 lengthMismatches=0/.test(line)) ok(`fuzz: ${line}`);
  else fail(`fuzz: ${line || 'no output'}`);
} catch (e) {
  fail(`fuzz: ${e.message}`);
}

console.log(`\n${failures === 0 ? 'ALL VERIFICATION CHECKS PASSED' : `${failures} CHECK(S) FAILED`}`);
process.exit(failures === 0 ? 0 : 1);
